-- Judo: nowa struktura Judo → Kobiety / Mężczyźni / Drużyna mieszana → kategorie wagowe.
-- Każda kategoria to osobna konkurencja z tablicą kwot (top 17 z rankingu IJF + gospodarz) i własnym rankingiem IJF.
-- Kwoty kontynentalne i miejsca uniwersalne – osobna zakładka zbiorcza u kobiet i mężczyzn.
-- Stare konkurencje judo (kobiety, mężczyźni, drużyna mieszana) są usuwane. Można uruchomić ponownie.

delete from public.konkurencje k using public.dyscypliny d
where d.id = k.dyscyplina_id and d.slug = 'judo' and k.slug in ('kobiety', 'mezczyzni', 'druzyna-mieszana');

insert into public.dyscypliny (slug, nazwa, nadrzedna_id, kolejnosc)
select v.slug, v.nazwa, j.id, v.kol
from (values ('judo-kobiety', 'Judo – kobiety', 1), ('judo-mezczyzni', 'Judo – mężczyźni', 2), ('judo-druzyna-mieszana', 'Judo – drużyna mieszana', 3)) as v(slug, nazwa, kol)
cross join (select id from public.dyscypliny where slug = 'judo') j
on conflict (slug) do update set nadrzedna_id = excluded.nadrzedna_id, nazwa = excluded.nazwa;

update public.dyscypliny set opis_kafla = v.opis from (values
  ('judo', 'Kobiety, mężczyźni i drużyna mieszana · ranking IJF'),
  ('judo-kobiety', '7 kategorii · top 17 z rankingu IJF + kwoty kontynentalne'),
  ('judo-mezczyzni', '7 kategorii · top 17 z rankingu IJF + kwoty kontynentalne'),
  ('judo-druzyna-mieszana', 'Drużyny z zawodników zakwalifikowanych indywidualnie')
) as v(slug, opis) where dyscypliny.slug = v.slug;

