-- Rankingi IJF przypięte do konkurencji kategorii
update public.zrodla_rankingow z set konkurencja_id = k.id
from (values
  ('ijf-m60', 'judo-mezczyzni', 'do-60-kg'), ('ijf-m66', 'judo-mezczyzni', 'do-66-kg'), ('ijf-m73', 'judo-mezczyzni', 'do-73-kg'),
  ('ijf-m81', 'judo-mezczyzni', 'do-81-kg'), ('ijf-m90', 'judo-mezczyzni', 'do-90-kg'), ('ijf-m100', 'judo-mezczyzni', 'do-100-kg'),
  ('ijf-mp100', 'judo-mezczyzni', 'powyzej-100-kg'),
  ('ijf-k48', 'judo-kobiety', 'do-48-kg'), ('ijf-k52', 'judo-kobiety', 'do-52-kg'), ('ijf-k57', 'judo-kobiety', 'do-57-kg'),
  ('ijf-k63', 'judo-kobiety', 'do-63-kg'), ('ijf-k70', 'judo-kobiety', 'do-70-kg'), ('ijf-k78', 'judo-kobiety', 'do-78-kg'),
  ('ijf-kp78', 'judo-kobiety', 'powyzej-78-kg')
) as v(zrodlo, sport, ev)
join public.dyscypliny d on d.slug = v.sport
join public.konkurencje k on k.dyscyplina_id = d.id and k.slug = v.ev
where z.slug = v.zrodlo;
